"import React, { useState, useEffect, useRef } from "react";
import { 
  Award, 
  HelpCircle, 
  Lightbulb, 
  BookOpen, 
  Code, 
  Cloud, 
  ShieldCheck, 
  X, 
  Info, 
  FileCode, 
  Compass, 
  Activity, 
  Server, 
  Cpu, 
  Database, 
  Lock, 
  CheckCircle,
  AlertTriangle,
  ZoomIn,
  ZoomOut,
  Maximize2
} from "lucide-react";

interface KnowledgeLink {
  label: string;
  path: string;
}

interface KnowledgeNode {
  id: string;
  label: string;
  subLabel: string;
  category: "user" | "mobile" | "backend" | "ai_db" | "deploy" | "security_test";
  stage: 1 | 2 | 3 | 4 | 5 | 6;
  x: number;
  y: number;
  w: number;
  h: number;
  summary: string; // Tóm tắt dòng chảy dữ liệu
  technicalDetails: string; // Chi tiết kỹ thuật & Cơ chế hoạt động
  files: { name: string; path: string }[]; // Các file code thực tế liên đới
  qaList: {
    question: string;
    answer: string;
  }[];
  rubricMapping: string; // Rubric / Báo cáo liên quan
}

interface KnowledgeEdge {
  from: string;
  to: string;
